import { Entity, Column, Index } from 'typeorm';
import { BaseEntity } from '../../../../database/base.entity';

/**
 * Expense Forecast Entity.
 * Projected future expense items generated by AI algorithms.
 */
@Entity('finance_expense_forecasts')
@Index('idx_finance_forecasts_user_date', ['userId', 'forecastDate'])
export class ExpenseForecast extends BaseEntity {
  @Index('idx_finance_forecasts_user_id')
  @Column({ type: 'uuid', name: 'user_id' })
  userId: string;

  @Column({ type: 'varchar', length: 255 })
  title: string;

  @Column({ type: 'uuid', name: 'category_id', nullable: true })
  categoryId: string | null;

  @Column({
    type: 'numeric',
    precision: 12,
    scale: 2,
    name: 'forecasted_amount',
    transformer: { to: (v: number) => v, from: (v: string) => parseFloat(v) },
  })
  forecastedAmount: number;

  @Column({ type: 'timestamp with time zone', name: 'forecast_date' })
  forecastDate: Date;

  @Column({
    type: 'numeric',
    precision: 5,
    scale: 2,
    name: 'confidence_score',
    default: 0.85,
    transformer: { to: (v: number) => v, from: (v: string) => parseFloat(v) },
  })
  confidenceScore: number;

  @Column({ type: 'text', nullable: true })
  notes: string | null;
}
